import "core-js/modules/es.array.push.js";
import { computed, ref, onMounted } from "vue";
import { useStore } from "vuex";
import { useRouter } from "vue-router";
import AboutIcon from "@/Icons/AboutIcon.vue";
import GiftIcon from "@/Icons/GiftIcon.vue";
import HomeIcon from "@/Icons/HomeIcon.vue";
import PhoneIcon from "@/Icons/PhoneIcon.vue";
import SharedAccount from "@/Icons/SharedAccount.vue";
import ArrowButtom from "@/Icons/ArrowBottom.vue";
import CopiedIcon from "@/Icons/CopiedIcon.vue";
import DoneCopied from "@/Icons/DoneCopied.vue";
import PlusIcon from "@/Icons/PlusIcon.vue";
import UnknowUser from "@/Icons/UnknowUser.vue";
import WeatherBlock from "@/components/WeatherBlock.vue";
import Modal from "@/components/Modal";
import QRCode from "qrcode-generator";
import vClickOutside from "click-outside-vue3";
import useTranslations from "@/composables/useTranslations";
import formatPhoneNumber from "@/composables/usePhoneFormatter";
import dayjs from "dayjs";
export default {
  name: "ProfileInfo",
  directives: {
    clickOutside: vClickOutside.directive
  },
  components: {
    GiftIcon,
    PhoneIcon,
    HomeIcon,
    AboutIcon,
    SharedAccount,
    CopiedIcon,
    DoneCopied,
    ArrowButtom,
    PlusIcon,
    UnknowUser,
    Modal,
    WeatherBlock
  },
  props: {
    me: Boolean,
    online: Boolean,
    blocked: Boolean,
    friend: Boolean,
    info: Object,
    text: String,
    infoFriend: Object
  },
  setup(props) {
    const {
      getters,
      dispatch
    } = useStore();
    const router = useRouter();
    const modalShow = ref(false);
    const modalText = ref("");
    const modalType = ref("deleteFriend");
    const showInfo = ref(false);
    const showInfoWeather = ref(false);
    const showEmojiStatus = ref(false);
    const showPopup = ref(false);
    const qrCode = ref("");
    const copied = ref(false);
    const showLoupe = ref(false);
    const showAvatar = ref(false);
    const showActions = ref(false);
    const textRef = ref(null);
    const activeLink = ref("");
    const page = ref(1);
    const size = ref(3);
    const {
      translationsLang
    } = useTranslations();
    const dialogs = computed(() => getters["profile/dialogs/dialogs"]);
    const getUsersInfo = computed(() => getters["users/info/getUsersInfo"]);
    const getWall = computed(() => getters["users/info/getWall"]);
    const getWallPagination = computed(() => getters["users/info/getWallPagination"]);
    const users = computed(() => getters["global/search/getResultByIdSearch"]("users"));
    const getUsersQueryParams = computed(() => getters["global/search/getUsersQueryParams"]);
    const currentUser = computed(() => getters.getUser);
    const usersByEmojiStatus = computed(() => {
      return users.value.reduce((acc, user) => {
        const {
          emojiStatus
        } = user;
        if (acc[emojiStatus]) {
          acc[emojiStatus].push(user);
        } else {
          acc[emojiStatus] = [user];
        }
        return acc;
      }, {});
    });
    const residenceText = computed(() => {
      let country = props.info?.country;
      let city = props.info?.city;
      if (!country && !city) {
        return null;
      }
      return `${country + ", " || ""} ${city || ""}`;
    });
    const currentUrl = computed(() => {
      if (props.me === true) {
        return `${window.location.origin}/profile/` + currentUser.value;
      } else {
        return window.location.href;
      }
    });
    const statusText = computed(() => {
      return props.online ? translationsLang.profileInfoStatusOnline : translationsLang.profileInfoStatusOffline;
    });
    onMounted(() => {
      const searchQuery = {
        ...getUsersQueryParams.value,
        page: page.value - 1,
        size: size.value
      };
      if (users.value.length === 0) {
        dispatch("global/search/searchUsers", {
          payload: searchQuery
        });
      }
    });
    const closeEmojiList = () => {
      showEmojiStatus.value = false;
    };
    const toggleEmojiStatus = () => {
      showEmojiStatus.value = !showEmojiStatus.value;
    };
    const getAgeAsString = age => {
      const ages = ["год", "года", "лет"];
      const n = parseInt(age, 10);
      return ages[n % 100 > 4 && n % 100 < 20 ? 2 : [2, 0, 1, 1, 1, 2][n % 10 < 5 ? n % 10 : 5]];
    };
    const copyText = () => {
      const range = document.createRange();
      range.selectNode(textRef.value);
      window.getSelection().removeAllRanges();
      window.getSelection().addRange(range);
    };
    const copyToClipboard = () => {
      const range = document.createRange();
      range.selectNode(textRef.value);
      window.getSelection().removeAllRanges();
      window.getSelection().addRange(range);
      document.execCommand("copy");
      copied.value = true;
    };
    const actionsShow = () => {
      showActions.value = !showActions.value;
    };
    const closeActions = () => {
      showActions.value = false;
    };
    const togglePopup = () => {
      const url = currentUrl.value;
      qrCode.value = generateQRCode(url);
      showPopup.value = !showPopup.value;
    };
    const closePopup = () => {
      window.getSelection().removeAllRanges();
      copied.value = false;
      showPopup.value = false;
    };
    const generateQRCode = url => {
      const qr = QRCode(0, "M");
      qr.addData(url);
      qr.make();
      return qr.createImgTag();
    };
    const scrollToPosts = () => {
      const posts = document.getElementById("mypublications");
      posts.scrollIntoView({
        behavior: "smooth"
      });
      activeLink.value = "link1";
    };
    const showMoreInfo = () => {
      showInfo.value = !showInfo.value;
    };
    const showWeather = () => {
      showInfoWeather.value = !showInfoWeather.value;
    };
    const addToFriend = id => {
      if (props.infoFriend.statusCode === "REQUEST_TO") {
        dispatch("global/alert/setAlert", {
          status: "action",
          text: "Вы уже отправляли запрос на добавления в друзья этому пользователю!"
        });
        return;
      }
      if (props.infoFriend.statusCode === "FRIEND") {
        dispatch("global/alert/setAlert", {
          status: "action",
          text: "Этот пользователь уже является вашим другом!"
        });
        return;
      }
      if (props.infoFriend.statusCode === "BLOCKED") {
        dispatch("global/alert/setAlert", {
          status: "action",
          text: "Вы заблокировали этого пользователя!"
        });
        return;
      }
      if (props.infoFriend.statusCode === "SUBSCRIBED") {
        dispatch("global/alert/setAlert", {
          status: "action",
          text: "Этот пользователь среди ваших подписчиков, для добавления в друзья необходимо удалить его из списка подписчиков!"
        });
        return;
      }
      if (props.infoFriend.statusCode !== "NONE" && props.infoFriend.statusCode !== null && props.infoFriend.statusCode == "WATCHING") {
        dispatch("global/alert/setAlert", {
          status: "action",
          text: "У вас уже есть отношения с этим пользователем, чтобы подписаться необходимо остановить другие отношения!"
        });
        return;
      }
      dispatch("profile/friends/apiAddFriends", {
        id
      });
      locationReload();
    };
    const locationReload = () => {
      setTimeout(() => {
        location.reload();
      }, 300);
    };
    const cancelApiRequests = id => {
      dispatch("profile/friends/apiDeleteFriends", {
        id
      });
      locationReload();
    };
    const acceptFriendRequest = id => {
      if (props.infoFriend.statusCode === "FRIEND") {
        dispatch("global/alert/setAlert", {
          status: "action",
          text: "Этот пользователь уже является вашим другом!"
        });
        return;
      }
      dispatch("profile/friends/apiAddFriends", {
        id,
        isApprove: true
      });
      locationReload();
    };
    const subscribe = id => {
      if (props.infoFriend.statusCode === "SUBSCRIBED") {
        dispatch("global/alert/setAlert", {
          status: "action",
          text: "Вы уже подписаны на этого пользователя!"
        });
        return;
      }
      if (props.infoFriend.statusCode === "FRIEND") {
        dispatch("global/alert/setAlert", {
          status: "action",
          text: "У вас уже есть отношения с этим пользователем, чтобы подписаться необходимо остановить другие отношения!"
        });
        return;
      }
      dispatch("profile/friends/apiSubscribe", {
        id
      });
      locationReload();
    };
    const blockedUser = id => {
      dispatch("users/actions/apiBlockedUser", {
        id
      });
      locationReload();
    };
    const unBlockedUser = id => {
      dispatch("users/actions/apiUnblockUser", {
        id
      });
      locationReload();
    };
    const closeModal = () => {
      modalShow.value = false;
    };
    const onSentMessage = () => {
      if (props.blocked) return false;
      router.push({
        name: "ImChat",
        params: {
          activeDialogId: props.info.id.toString()
        }
      });
    };
    const formatLastTime = time => {
      return dayjs(time).fromNow();
    };
    const searchUsers = () => {
      dispatch("global/search/searchUsers");
    };
    const getInfo = () => {
      getters("profile/info/getInfo");
    };
    // const userInfoId = () => {
    //   dispatch('users/info/userInfoId');
    // };
    // const createDialogWithUser = () => {
    //   dispatch('profile/dialogs/createDialogWithUser');
    // };
    // const apiLoadAllDialogs = () => {
    //   dispatch('profile/dialogs/apiLoadAllDialogs');
    // };

    return {
      modalShow,
      modalText,
      modalType,
      showEmojiStatus,
      showPopup,
      qrCode,
      copied,
      showLoupe,
      showAvatar,
      showActions,
      textRef,
      translationsLang,
      dialogs,
      getUsersInfo,
      getWall,
      getWallPagination,
      users,
      usersByEmojiStatus,
      residenceText,
      statusText,
      closeEmojiList,
      toggleEmojiStatus,
      getAgeAsString,
      copyText,
      copyToClipboard,
      actionsShow,
      closeActions,
      togglePopup,
      closePopup,
      scrollToPosts,
      showMoreInfo,
      showWeather,
      addToFriend,
      cancelApiRequests,
      acceptFriendRequest,
      subscribe,
      blockedUser,
      unBlockedUser,
      closeModal,
      onSentMessage,
      formatLastTime,
      searchUsers,
      getInfo,
      formatPhoneNumber
    };
  }
};
